async function exportReport() { if (exporting.value) return; exporting.value = true; const finishRequest = beginGlobalRequest(); exportError.value = ''; exportSuccess.value = false; try { const url = new URL('/reports/export', window.location.origin); if (from.value) url.searchParams.set('from', from.value); if (to.value) url.searchParams.set('to', to.value); const response = await fetch(url, { credentials: 'same-origin', headers: { Accept: 'text/csv', 'X-Requested-With': 'XMLHttpRequest' } }); if (!response.ok) throw new Error('Não foi possível exportar o relatório.'); const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `reports-${from.value || 'inicio'}-${to.value || 'fim'}.csv`; link.click(); URL.revokeObjectURL(link.href); exportSuccess.value = true } catch (error) { exportError.value = error instanceof Error ? error.message : 'Não foi possível exportar o relatório.' } finally { finishRequest(); exporting.value = false } }
